          const sw = await connectSession(scan2Targets[i], `sw-x16-${i}`)
          await ensureSessionReady(sw)
          const seenRaw = await evalIn(sw, `chrome.tabs.query({}).then(
            (ts) => JSON.stringify(ts.map((t) => String(t.url || '')))
          ).catch(() => '[]')`, true)
