      let incogLeak = -1
      if (incogUrl) {
        const scan2Targets = (await getTargetList(args.port)).filter((t) => String(t.url).endsWith('/sw.js'))
        let leak = 0
        for (let i = 0; i < scan2Targets.length; i++) {
