        for (let cycle = 0; cycle < 3 && switchTargets.length === 2; cycle++) {
          // 1) 닫을 창 확보 — 첫 바퀴는 X16 이 연 시크릿 창을 그대로 쓰고, 이후엔 새로 연다.
