    // ---- X3/X4 서비스 워커 + storage ----
    {
      const swTarget = (await getTargetList(args.port))
        .find((t) => String(t.url).startsWith('chrome-extension://') && /sw\.js|service_worker|background/.test(String(t.url) + String(t.title)))
