        await sleep(3500)   // 제거도 디스크→폴링을 거친다
        pages.resetHits()
        await evalIn(p1, `fetch('/dyn/b.js').then(() => 'ok').catch(() => 'blocked')`, true)
        loadedAfterRemove = pages.dynHits > 0
        try { sw.close() } catch { /* ignore */ }
