      }

      check('X25', '확장이 id 를 추측해도 **시크릿 탭의 DOM 은 바꾸지 못한다**(executeScript 실제 변조)',
        judgeX25IncognitoInjection(x25),
        `${x25.note} · 훑은 확장 세션 ${x25.sweptSessions ?? 0}개(그중 대조 탭을 못 보는 다른 세션 ${x25.foreignSessions ?? 0}개)`
