const eager = new Set<number>()
w.tabs.forEach((t, i) => { if (t.active || t.pinned) eager.add(i) })
for (let i = Math.max(0, w.tabs.length - EAGER_TAIL); i < w.tabs.length; i += 1) eager.add(i)
// 분할(타일링) pane 의 탭은 **복원 직후 화면에 보인다** — 잠자는 채로 두면 사용자는
