for (const layout of w.layouts ?? []) {
  for (const p of layout.panes ?? []) {
    if (typeof p?.tabIndex === 'number') {
      const i = w.tabs.findIndex((t) => t.index === p.tabIndex && t.workspaceId === layout.workspaceId)
      if (i >= 0) eager.add(i)
    }
  }
