  const logStream = fs.createWriteStream(path.join(args.out, 'app.log'))
  // let(재시작 시 재할당) — X20/X23 이 앱을 껐다 켠다.
  let child = spawn(EXE, [`--remote-debugging-port=${args.port}`, `--user-data-dir=${profileDir}`],
    { stdio: ['ignore', 'pipe', 'pipe'] })
